"use strict";

const $ = id => document.getElementById(id);
const demo = new URLSearchParams(location.search).has("demo");
const key = "stagehand.inventory.v1";
const sample = {
  boxes: [
    {id:1, name:"Drawing room", notes:"Keep upright"},
    {id:2, name:"Desk dressing", notes:""}
  ],
  props: [
    {id:1, name:"Porcelain teapot", notes:"Lid wrapped separately", box:1},
    {id:2, name:"Brass candlestick", notes:"", box:1},
    {id:3, name:"Letter opener", notes:"", box:2},
    {id:4, name:"Pocket watch", notes:"Return to costume rail after move", box:null}
  ]
};
let data = demo ? sample : {boxes:[], props:[]};
let saved = null;
let storageMessage = "";
let locked = false;
if (!demo) {
  try {
    saved = localStorage.getItem(key);
  } catch {
    storageMessage = "Session only · browser storage unavailable";
  }
  if (saved !== null) {
    try {
      const stored = JSON.parse(saved);
      for (const list of [stored.boxes, stored.props]) {
        if (!Array.isArray(list) || new Set(list.map(x => x.id)).size !== list.length ||
          !list.every(x => Number.isSafeInteger(x.id) && x.id > 0 && typeof x.name === "string" && typeof x.notes === "string")) throw Error();
      }
      if (!stored.props.every(p => p.box === null || stored.boxes.some(b => b.id === p.box))) throw Error();
      data = stored;
    } catch {
      locked = true;
      storageMessage = "Saved inventory could not be read. Editing is disabled to protect it.";
    }
  }
}
let view = "boxes";
let editing;
const dialog = document.querySelector("dialog");
function element(tag, text, className) {
  const node = document.createElement(tag);
  if (text !== undefined) node.textContent = text;
  if (className) node.className = className;
  return node;
}
function editButton(kind, record) {
  const button = element("button", "Edit", "edit");
  button.setAttribute("aria-label", "Edit " + record.name);
  button.disabled = locked;
  button.onclick = () => openForm(kind, record);
  return button;
}
function propRow(prop) {
  const row = element("div", undefined, "row");
  const detail = element("div");
  detail.append(element("strong", prop.name));
  if (prop.notes) detail.append(element("p", prop.notes, "note"));
  row.append(detail, editButton("props", prop));
  return row;
}
function boxLabel(box) {
  return "Box " + String(box.id).padStart(2, "0");
}
function printGroup(title, notes, props) {
  const group = element("section");
  group.append(element("h2", title));
  if (notes) group.append(element("p", notes, "boxNote"));
  const list = element("ul");
  for (const prop of props) {
    const item = element("li", prop.name);
    if (prop.notes) item.append(element("p", prop.notes));
    list.append(item);
  }
  group.append(props.length ? list : element("p", "No props"));
  $("paper").append(group);
}
function render() {
  const loose = data.props.filter(p => p.box === null);
  $("stats").replaceChildren();
  for (const [value, label] of [[data.boxes.length,"boxes"], [data.props.length,"props"], [loose.length,"unassigned"]]) {
    const stat = element("span");
    stat.append(element("b", value), label);
    $("stats").append(stat);
  }
  $("boxesTab").setAttribute("aria-pressed", view === "boxes");
  $("looseTab").setAttribute("aria-pressed", view === "loose");
  const work = $("work");
  work.replaceChildren(element("h2", view === "boxes" ? "Box inventory" : "Unassigned props"));
  $("paper").replaceChildren(element("h1", demo ? "Sample packing inventory" : "Packing inventory"),
    element("p", data.boxes.length + " boxes · " + data.props.length + " props · " + loose.length + " unassigned"));
  for (const box of data.boxes) {
    const contents = data.props.filter(p => p.box === box.id);
    printGroup(boxLabel(box) + " — " + box.name, box.notes, contents);
    if (view !== "boxes") continue;
    const card = element("section", undefined, "card");
    const head = element("div", undefined, "cardHead");
    const title = element("div");
    title.append(element("span", boxLabel(box).toUpperCase(), "tag"), element("h3", box.name));
    if (box.notes) title.append(element("p", box.notes, "note"));
    head.append(title, editButton("boxes", box));
    card.append(head);
    for (const p of contents) card.append(propRow(p));
    if (!contents.length) card.append(element("p", "No props in this box yet.", "vacant"));
    work.append(card);
  }
  printGroup("Unassigned props", "", loose);
  if (view === "boxes" && !data.boxes.length) work.append(element("div", "Add your first box to start a packing list.", "empty"));
  if (view === "loose") {
    const list = element("div", undefined, loose.length ? "card" : "empty");
    if (!loose.length) list.textContent = "No props awaiting a box.";
    for (const p of loose) list.append(propRow(p));
    work.append(list);
  }
  $("status").textContent = demo ? "Sample move · resets when reloaded" : storageMessage || "Local inventory · saved in this browser";
  $("addBox").disabled = $("addProp").disabled = locked;
}
function openForm(kind, record) {
  editing = {kind, record};
  const isProp = kind === "props";
  $("formTitle").textContent = (record ? "Edit " : "Add ") + (isProp ? "prop" : "box");
  $("name").value = record?.name || "";
  $("name").setCustomValidity("");
  $("notes").value = record?.notes || "";
  $("assignment").hidden = !isProp;
  $("box").replaceChildren(new Option("Unassigned", ""));
  for (const box of data.boxes) $("box").add(new Option(boxLabel(box) + " — " + box.name, box.id));
  $("box").value = record?.box ?? "";
  dialog.showModal();
  $("name").focus();
}
$("name").oninput = () => $("name").setCustomValidity("");
$("form").onsubmit = event => {
  event.preventDefault();
  const name = $("name").value.trim();
  if (!name) {
    $("name").setCustomValidity("Enter a name.");
    $("name").reportValidity();
    return;
  }
  const {kind, record} = editing;
  const list = data[kind];
  const item = {id:record?.id ?? (list.reduce((n,x) => Math.max(n,x.id),0) + 1), name, notes:$("notes").value.trim()};
  if (kind === "props") item.box = Number($("box").value) || null;
  const next = {...data, [kind]:record ? list.map(x => x.id === record.id ? item : x) : [...list,item]};
  if (!demo) {
    try {
      if (localStorage.getItem(key) !== saved) {
        dialog.close();
        locked = true;
        storageMessage = "Inventory changed in another window. Reload to continue.";
        render();
        return;
      }
      const encoded = JSON.stringify(next);
      localStorage.setItem(key, encoded);
      saved = encoded;
      storageMessage = "";
    } catch {
      storageMessage = "Session only · changes could not be saved. Print before closing.";
    }
  }
  data = next;
  view = kind === "props" && item.box === null ? "loose" : "boxes";
  dialog.close();
  render();
};
$("addBox").onclick = () => openForm("boxes");
$("addProp").onclick = () => openForm("props");
$("cancel").onclick = () => dialog.close();
$("boxesTab").onclick = () => { view = "boxes"; render(); };
$("looseTab").onclick = () => { view = "loose"; render(); };
$("print").onclick = () => window.print();
if (demo) {
  $("demoLink").href = location.pathname;
  $("demoLink").textContent = "Return to local inventory";
}
render();

"use strict";

const byId = (id) => document.getElementById(id);
const storageKey = "prop-load.inventory.v1";
const emptyInventory = () => ({ example: false, boxes: [], props: [] });

const editor = byId("editor");
const form = byId("editor-form");
const nameField = byId("record-name");
const noteField = byId("box-note");
const quantityField = byId("quantity");
const boxField = byId("prop-box");
const deleteButton = byId("delete-record");
const exampleButton = byId("load-example");
const printButton = byId("print-button");

let canSave = true;
let inventory = readInventory();
let filter = "all";
let editing;

function storageProblem(message) {
  byId("storage-note").textContent = "Current session only.";
  const error = byId("storage-error");
  error.textContent = message;
  error.hidden = false;
}

function readInventory() {
  try {
    const saved = localStorage.getItem(storageKey);
    if (saved === null) return emptyInventory();
    const data = JSON.parse(saved);
    if (!validInventory(data)) throw new Error("Invalid inventory data");
    return data;
  } catch {
    canSave = false;
    storageProblem("Saved inventory could not be opened. Changes made in this session will be lost when you close or reload this page.");
    return emptyInventory();
  }
}

function validInventory(data) {
  if (!data || typeof data.example !== "boolean" || !Array.isArray(data.boxes) || !Array.isArray(data.props)) {
    return false;
  }
  const boxesValid = data.boxes.every((box) => box && Number.isSafeInteger(box.id)
    && typeof box.name === "string" && typeof box.note === "string");
  return boxesValid && data.props.every((prop) => prop && Number.isSafeInteger(prop.id)
    && typeof prop.name === "string" && Number.isInteger(prop.quantity) && prop.quantity >= 1
    && (prop.boxId === null || data.boxes.some((box) => box.id === prop.boxId)));
}

function commit(message) {
  if (canSave) {
    try {
      localStorage.setItem(storageKey, JSON.stringify(inventory));
      byId("storage-note").textContent = "Stored in this browser.";
      byId("storage-error").hidden = true;
    } catch {
      storageProblem("The browser could not save your changes. Keep this page open to keep working.");
    }
  }
  render();
  byId("status").textContent = message;
}

function element(tag, text, className) {
  const node = document.createElement(tag);
  if (text !== undefined) node.textContent = text;
  if (className) node.className = className;
  return node;
}

function entryCount(count) {
  return `${count} prop ${count === 1 ? "entry" : "entries"}`;
}

function fillBoxSelect(select, selected) {
  select.replaceChildren(new Option("Unassigned", ""));
  for (const box of inventory.boxes) {
    select.add(new Option(box.name, String(box.id)));
  }
  select.value = selected === null ? "" : String(selected);
}

function selectedBox(select) {
  return select.value === "" ? null : Number(select.value);
}

function recordRow(item, type, detail) {
  const row = element("li", undefined, "record");
  const text = element("div", undefined, "record-content");
  text.append(element("strong", item.name), element("span", detail, "record-detail"));
  const controls = element("div", undefined, "record-controls");
  const edit = element("button", "Edit", "row-action");
  edit.type = "button";
  edit.setAttribute("aria-label", `Edit ${type} ${item.name}`);
  edit.addEventListener("click", () => openEditor(type, item));
  controls.append(edit);
  row.append(text, controls);
  return { row, controls };
}

function renderProp(prop) {
  const { row, controls } = recordRow(prop, "prop", `Qty ${prop.quantity}`);
  const select = element("select");
  select.id = `assignment-${prop.id}`;
  select.setAttribute("aria-label", `Box for ${prop.name}`);
  select.toggleAttribute("data-unassigned", prop.boxId === null);
  fillBoxSelect(select, prop.boxId);
  select.addEventListener("change", () => {
    prop.boxId = selectedBox(select);
    commit(`Box for ${prop.name} updated.`);
    (byId(select.id) || document.querySelector('[data-filter="unassigned"]')).focus();
  });
  controls.prepend(select);
  return row;
}

function render() {
  const unassigned = inventory.props.filter((prop) => prop.boxId === null);
  const shownProps = filter === "unassigned" ? unassigned : inventory.props;
  byId("box-total").textContent = inventory.boxes.length;
  byId("prop-total").textContent = inventory.props.length;
  byId("unassigned-total").textContent = unassigned.length;

  byId("props").replaceChildren(...shownProps.map(renderProp));
  const propsEmpty = byId("props-empty");
  propsEmpty.hidden = shownProps.length > 0;
  propsEmpty.textContent = filter === "unassigned"
    ? "No unassigned props."
    : "Add a prop to start your packing list.";

  byId("boxes").replaceChildren(...inventory.boxes.map((box) => {
    const count = inventory.props.filter((prop) => prop.boxId === box.id).length;
    const detail = box.note ? `${entryCount(count)} · ${box.note}` : entryCount(count);
    return recordRow(box, "box", detail).row;
  }));
  byId("boxes-empty").hidden = inventory.boxes.length > 0;

  for (const button of document.querySelectorAll("[data-filter]")) {
    button.setAttribute("aria-pressed", String(button.dataset.filter === filter));
  }
  const hasRecords = inventory.boxes.length > 0 || inventory.props.length > 0;
  printButton.disabled = !hasRecords;
  exampleButton.hidden = inventory.example || hasRecords;
  byId("clear-example").hidden = !inventory.example;
  document.querySelector(".eyebrow").textContent = inventory.example ? "Example inventory" : "Backstage logistics";
  renderPrint(unassigned);
}

function renderPrint(unassigned) {
  const report = byId("print-inventory");
  const boxCount = inventory.boxes.length;
  report.replaceChildren(
    element("h1", inventory.example ? "Example packing inventory" : "Packing inventory"),
    element("p", `${boxCount} ${boxCount === 1 ? "box" : "boxes"} · ${entryCount(inventory.props.length)} · ${unassigned.length} unassigned`)
  );
  const groups = inventory.boxes.map((box) => ({
    title: `Box ${box.name}`,
    note: box.note,
    props: inventory.props.filter((prop) => prop.boxId === box.id)
  }));
  if (unassigned.length) groups.push({ title: "Unassigned props", props: unassigned });
  for (const group of groups) {
    const section = element("section");
    section.append(element("h2", group.title));
    if (group.note) section.append(element("p", group.note, "print-note"));
    if (group.props.length) {
      const table = element("table");
      const headings = table.createTHead().insertRow();
      for (const label of ["Prop", "Qty"]) {
        const heading = element("th", label);
        heading.scope = "col";
        headings.append(heading);
      }
      const body = table.createTBody();
      for (const prop of group.props) {
        const row = body.insertRow();
        row.insertCell().textContent = prop.name;
        row.insertCell().textContent = prop.quantity;
      }
      section.append(table);
    } else {
      section.append(element("p", "No props assigned."));
    }
    report.append(section);
  }
}

function openEditor(type, item) {
  editing = { type, item };
  const isProp = type === "prop";
  byId("editor-title").textContent = `${item ? "Edit" : "Add"} ${type}`;
  byId("name-label").textContent = isProp ? "Prop name" : "Box label";
  byId("prop-fields").hidden = !isProp;
  byId("box-fields").hidden = isProp;
  deleteButton.hidden = !item;
  nameField.setCustomValidity("");
  nameField.value = item?.name ?? "";
  noteField.value = isProp ? "" : item?.note ?? "";
  quantityField.disabled = !isProp;
  quantityField.required = isProp;
  quantityField.value = isProp ? item?.quantity ?? 1 : 1;
  fillBoxSelect(boxField, isProp ? item?.boxId ?? null : null);
  editor.showModal();
}

function closeAfterChange(message) {
  editor.close();
  commit(message);
  byId(editing.type === "prop" ? "props-heading" : "boxes-heading").focus();
}

nameField.addEventListener("input", () => nameField.setCustomValidity(""));
form.addEventListener("submit", (event) => {
  event.preventDefault();
  const { type, item } = editing;
  const name = nameField.value.trim();
  const records = type === "prop" ? inventory.props : inventory.boxes;
  if (!name) {
    nameField.setCustomValidity(type === "prop" ? "Enter a prop name." : "Enter a box label.");
  } else if (type === "box" && records.some((box) => box !== item && box.name.toLowerCase() === name.toLowerCase())) {
    nameField.setCustomValidity("This box label is already in use.");
  }
  if (!nameField.reportValidity()) return;

  const values = type === "prop"
    ? { name, quantity: quantityField.valueAsNumber, boxId: selectedBox(boxField) }
    : { name, note: noteField.value.trim() };
  if (item) {
    Object.assign(item, values);
  } else {
    const id = records.reduce((highest, record) => Math.max(highest, record.id), 0) + 1;
    records.push({ id, ...values });
  }
  if (type === "prop" && !item && values.boxId !== null) filter = "all";
  closeAfterChange(`${name} ${item ? "updated" : "added"}.`);
});

deleteButton.addEventListener("click", () => {
  const { type, item } = editing;
  const count = type === "box" ? inventory.props.filter((prop) => prop.boxId === item.id).length : 0;
  const action = count ? ` ${entryCount(count)} will become unassigned.` : "";
  if (!window.confirm(`Delete ${item.name}?${action}`)) return;
  if (type === "box") {
    for (const prop of inventory.props) {
      if (prop.boxId === item.id) prop.boxId = null;
    }
    inventory.boxes = inventory.boxes.filter((box) => box !== item);
  } else {
    inventory.props = inventory.props.filter((prop) => prop !== item);
  }
  const reassigned = count ? ` ${entryCount(count)} now unassigned.` : "";
  closeAfterChange(`${item.name} deleted.${reassigned}`);
});

byId("cancel-editor").addEventListener("click", () => editor.close());
for (const button of document.querySelectorAll("[data-add]")) {
  button.addEventListener("click", () => openEditor(button.dataset.add));
}
for (const button of document.querySelectorAll("[data-filter]")) {
  button.addEventListener("click", () => {
    filter = button.dataset.filter;
    render();
    byId("status").textContent = `${entryCount(byId("props").childElementCount)} shown.`;
  });
}

exampleButton.addEventListener("click", () => {
  inventory = {
    example: true,
    boxes: [
      { id: 1, name: "A-01", note: "Stage left · Fragile" },
      { id: 2, name: "A-02", note: "Props table" },
      { id: 3, name: "B-01", note: "Storage rack" }
    ],
    props: [
      { id: 1, name: "Brass candlesticks", quantity: 2, boxId: 1 },
      { id: 2, name: "Porcelain teapot", quantity: 1, boxId: 1 },
      { id: 3, name: "Velvet drawstring pouch", quantity: 3, boxId: 2 },
      { id: 4, name: "Framed portrait", quantity: 1, boxId: null },
      { id: 5, name: "Wooden calling cards", quantity: 6, boxId: null }
    ]
  };
  filter = "all";
  commit("Example inventory loaded.");
  byId("props-heading").focus();
});

byId("clear-example").addEventListener("click", () => {
  if (!window.confirm("Remove the example inventory and any edits made to it?")) return;
  inventory = emptyInventory();
  filter = "all";
  commit("Example inventory removed.");
  exampleButton.focus();
});

printButton.addEventListener("click", () => window.print());
render();

:root {
  color-scheme: light;
  --paper: #f7f3ec;
  --panel: #fffdf9;
  --ink: #2d2230;
  --quiet: #675d66;
  --line: #ded4cb;
  --plum: #402641;
  --accent: #f2bfa4;
  --warning: #77351e;
  --warm: #fbe8d9;
  font: 100%/1.5 system-ui, sans-serif;
  color: var(--ink);
  background: var(--paper);
}
* { box-sizing: border-box; }
body { margin: 0; }
[hidden] { display: none !important; }
.wrap { width: min(71rem, calc(100% - 3rem)); margin-inline: auto; }
.masthead { background: var(--plum); color: #fff9f4; }
.masthead-inner, .intro, .panel-top, .record, footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
}
.masthead-inner { min-height: 4.5rem; }
.wordmark { display: flex; align-items: center; gap: .75rem; font-weight: 750; letter-spacing: .02em; }
.mark {
  width: 1.22rem;
  height: 1.22rem;
  border: 2px solid var(--accent);
  border-radius: 3px;
  position: relative;
}
.mark::after {
  content: "";
  position: absolute;
  width: .32rem;
  height: .55rem;
  inset: -2px auto auto 50%;
  transform: translateX(-50%);
  border: 2px solid var(--accent);
  border-radius: 0 0 2px 2px;
}
h1, h2, h3, p { margin: 0; }
h1, h2 { font-family: Georgia, serif; font-weight: normal; }
h1 { font-size: clamp(2.8rem, 7vw, 4.5rem); line-height: 1.02; letter-spacing: -.045em; margin: .35rem 0 .7rem; }
h2 { font-size: 1.9rem; line-height: 1.15; letter-spacing: -.025em; }
.intro { align-items: end; padding-block: 2.75rem 1.75rem; }
.intro p, .empty, .record-detail, footer { color: var(--quiet); }
.intro .eyebrow {
  color: var(--warning);
  font: 700 .76rem/1.4 ui-monospace, monospace;
  text-transform: uppercase;
  letter-spacing: .12em;
}
.stats {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  border: 1px solid var(--line);
  border-radius: .75rem;
  overflow: hidden;
  background: var(--panel);
}
.stats div { padding: .8rem 1.2rem; }
.stats div + div { border-left: 1px solid var(--line); }
.stats strong { display: block; font-size: 1.8rem; font-variant-numeric: tabular-nums; line-height: 1.2; }
.stats span { font-size: .875rem; }
.stats .attention { background: var(--warm); color: var(--warning); }
.workspace-grid { display: grid; grid-template-columns: minmax(0, 1.7fr) minmax(0, 1fr); gap: 1rem; margin-block: 1.25rem; align-items: start; }
.panel { background: var(--panel); border: 1px solid var(--line); border-radius: .75rem; overflow: hidden; }
.panel-top { padding: 1rem 1.2rem; border-bottom: 1px solid var(--line); }
button, input, select { font: inherit; color: inherit; min-height: 44px; }
button {
  cursor: pointer;
  border: 1px solid transparent;
  border-radius: .4rem;
  padding: .5rem .85rem;
  font-size: .875rem;
  font-weight: 690;
  background: transparent;
}
button:disabled { opacity: .55; cursor: default; }
.primary { background: var(--plum); color: white; }
.primary:hover { background: #583858; }
.secondary { border-color: #b9aab6; background: var(--panel); }
.secondary:hover, .row-action:hover, footer button:hover { background: #f1e6e9; }
.print-button { border-color: #b394ab; color: #fff9f4; }
.print-button:hover:not(:disabled) { background: #593a59; }
:focus-visible { outline: 2px solid #9c431f; outline-offset: 3px; }
.masthead :focus-visible { outline-color: var(--accent); }
.filters { display: flex; flex-wrap: wrap; gap: .5rem; padding: .65rem 1.2rem; border-bottom: 1px solid var(--line); }
.filters button { color: var(--quiet); }
.filters button:hover, .filters button[aria-pressed="true"] { background: #eee4ec; color: var(--plum); }
.records { margin: 0; padding: 0; list-style: none; }
.record { padding: .65rem 1.2rem; }
.record + .record { border-top: 1px solid var(--line); }
.record-content { min-width: 0; overflow-wrap: anywhere; }
.record-detail { display: block; font-size: .875rem; }
.record-controls { display: flex; align-items: center; gap: .5rem; min-width: 0; }
.record-controls select { width: 10.5rem; max-width: 100%; font-size: .875rem; }
select, input { border: 1px solid #aea0ab; border-radius: .4rem; padding: .45rem .65rem; background: var(--panel); }
select[data-unassigned] { background: var(--warm); color: var(--warning); border-color: #c58e72; }
.row-action { border-color: var(--line); }
.empty { padding: 1.5rem 1.2rem; }
footer { font-size: .875rem; flex-wrap: wrap; margin: 0 0 2rem; }
footer button { text-decoration: underline; }
.storage-error { color: var(--warning); padding: .75rem; background: var(--warm); margin-bottom: 1rem; }
dialog { width: min(28rem, calc(100% - 2rem)); border: 1px solid var(--line); border-radius: .75rem; background: var(--panel); color: var(--ink); padding: 1.4rem; }
dialog::backdrop { background: #231424a6; }
dialog label { display: block; font-weight: 650; margin: 1rem 0 .3rem; }
dialog input, dialog select { width: 100%; }
.dialog-actions { display: flex; flex-wrap: wrap; justify-content: end; gap: .5rem; margin-top: 1.25rem; }
.danger { color: #9b2c24; margin-right: auto; }
.danger:hover { background: #f8e2df; }
.sr-only { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }
#print-inventory { display: none; }
@media (max-width: 53rem) {
  .workspace-grid { grid-template-columns: minmax(0, 1fr); }
}
@media (max-width: 33rem) {
  .wrap { width: calc(100% - 1.5rem); }
  .intro { flex-wrap: wrap; align-items: start; padding-top: 1.8rem; }
  .stats div, .panel-top, .record, .filters { padding-inline: .75rem; }
  .record:has(select) { flex-wrap: wrap; gap: .5rem; }
  .record:has(select) .record-content { width: 100%; }
}
@page { margin: 15mm; }
@media print {
  :root { background: white; color: black; font: 11pt/1.4 system-ui, sans-serif; }
  #workspace { display: none; }
  #print-inventory { display: block; overflow-wrap: anywhere; }
  #print-inventory h1 { font-size: 26pt; margin: 0 0 .3em; }
  #print-inventory h2 { font: bold 14pt/1.3 system-ui, sans-serif; margin-top: 1.25em; border-bottom: 1pt solid; padding-bottom: .2em; break-after: avoid; }
  #print-inventory h2 + p { margin-top: .3em; }
  #print-inventory .print-note { break-after: avoid; }
  table { width: 100%; border-collapse: collapse; margin-top: .3em; }
  th, td { text-align: left; padding: .25em .4em .25em 0; border-bottom: .5pt solid #aaa; vertical-align: top; }
  th:last-child, td:last-child { width: 5em; text-align: right; }
  tr { break-inside: avoid; }
}
